export const getDeleteExpenseUrl = (expenseId: string,) => {




  return `/finance/expenses/${expenseId}`
}

/**
 * @summary Delete an expense
 */
export const deleteExpense = async (expenseId: string, options?: RequestInit): Promise<deleteExpenseResponse> => {

  const res = await fetch(getDeleteExpenseUrl(expenseId),
  {
    ...options,
    method: 'DELETE'


  }
)


  const body = [204, 205, 304].includes(res.status) ? null : await res.text();

  const data: deleteExpenseResponse['data'] = body ? JSON.parse(body) : undefined
  return { data, status: res.status, headers: res.headers } as deleteExpenseResponse
}


export type reportTransactionIssueResponse201 = {
  data: ReportTransactionIssue201
  status: 201
}

export type reportTransactionIssueResponseSuccess = (reportTransactionIssueResponse201) & {
  headers: Headers;
};
;

export type reportTransactionIssueResponse = (reportTransactionIssueResponseSuccess)

export const getReportTransactionIssueUrl = (transactionId: string,) => {




  return `/finance/transactions/${transactionId}/issue`
}

/**
 * @summary Report an issue on a transaction (amount mismatch, missing items)
 */
export const reportTransactionIssue = async (transactionId: string,
    reportTransactionIssueBody: ReportTransactionIssueBody, options?: RequestInit): Promise<reportTransactionIssueResponse> => {

  const res = await fetch(getReportTransactionIssueUrl(transactionId),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...options?.headers },
    body: JSON.stringify(reportTransactionIssueBody)
  }
)


  const body = [204, 205, 304].includes(res.status) ? null : await res.text();

  const data: reportTransactionIssueResponse['data'] = body ? JSON.parse(body) : {}
  return { data, status: res.status, headers: res.headers } as reportTransactionIssueResponse
}


